<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\RequestInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcFlowContext;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Authentication\Application\SessionManager;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\OidcCookieManager;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\OidcResponseBuilder;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcUrlBuilder;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ValueObject\PkceChallenge;
use Civi\Lughauth\Features\Oidc\Client\Domain\ClientData;
use Civi\Lughauth\Features\Oidc\Client\Domain\Gateway\ClientStoreGateway;

class AuthorizeHtml
{
    public function __construct(
        private readonly Context $context,
        private readonly ClientStoreGateway $clients,
        private readonly SessionManager $sessions,
        private readonly AuthenticateUser $authenticator,
        private readonly HtmlSecurer $securer,
        private readonly DecorateHtml  $decorator,
        private readonly OidcResponseBuilder $responseBuilder,
        private readonly OidcCookieManager $cookies,
        private readonly OidcUrlBuilder $urlBuilder,
        private readonly OidcStepRouter $router
    ) {
    }


    public function authorize(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $flow = $this->buildContext($request, $tenant);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $pkceError = $this->requirePkce($flow, $response);
        if ($pkceError !== null) {
            return $pkceError;
        }
        $authRequest = $this->buildAuthRequest($flow, $client);
        $sess = $this->sessions->loadSession($flow->sessionId ?? '', $flow->nonce, $flow->state);
        if ($sess) {
            return $this->cisdPage($request, $response, $flow, $authRequest);
        } elseif ("none" === $flow->prompt) {
            return $this->redirectError($tenant, $flow->redirect, 'No session', $response);
        } else {
            $input = $this->buildStepInput($flow, $request, $authRequest, new ChallengesState(), []);
            return $this->renderStep(null, null, $input, $response, null, $input->challenges);
        }
    }

    public function refresh(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $body = (array) ($request->getParsedBody() ?? []);
        $tenant = $args['tenant'];
        $flow = $this->buildContext($request, $tenant);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $pkceError = $this->requirePkce($flow, $response);
        if ($pkceError !== null) {
            return $pkceError;
        }
        $authRequest = $this->buildAuthRequest($flow, $client);
        $csid = $this->securer->verifyToken($body['csid']);
        if ($csid === null) {
            throw new UnauthorizedException();
        }
        $sess = $this->sessions->loadSession($flow->sessionId ?? '', $flow->nonce, $flow->state);
        if ($sess) {
            if ($csid !== $sess->csid) {
                return $this->redirectToLogin($response, $flow, $authRequest);
            }
            $challenges = (new ChallengesState())
                ->withUsername($sess->userId)
                ->withMfa($sess->withMfa)
                ->withSession(true);
            // auth-csid
            $auth = $this->authenticator->sessionAuthenticated($authRequest, $challenges, $tenant, $flow->issuer, $csid, $flow->state, $flow->nonce);
            return $this->responseBuilder->buildSuccessRedirect($flow, $auth, $client, $authRequest, $response);
        } else {
            return $this->redirectToLogin($response, $flow, $authRequest);
        }
    }

    public function formAuthorize(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $body = (array) ($request->getParsedBody() ?? []);
        $tenant = $args['tenant'];
        $flow = $this->buildContext($request, $tenant);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $pkceError = $this->requirePkce($flow, $response);
        if ($pkceError !== null) {
            return $pkceError;
        }
        $clientRequest = $this->buildAuthRequest($flow, $client);
        $state = new ChallengesState();
        if ($flow->preSessionId !== null && $flow->preSessionId !== '') {
            $state = $this->cookies->loadPreSessionChallenges($tenant, $flow->preSessionId);
        }
        $step = $body['step'] ?? null;
        $input = $this->buildStepInput($flow, $request, $clientRequest, $state, $body);
        try {
            // Tengo que sacar la password de fuera
            $csid = null;
            if (isset($body['csid'])) {
                $csid = $this->securer->verifyToken($body['csid']);
                if ($csid === null) {
                    throw new UnauthorizedException('missingin_csid');
                }
            }

            $result = $this->executeStep($input, $response, null, $step, $csid);
            if ($result->type === StepResult::TYPE_PROCEED && $result->authResponse) {
                return $this->responseBuilder->buildSuccessRedirect($flow, $result->authResponse, $client, $clientRequest, $response);
            }
            if ($result->type === StepResult::TYPE_RENDER && $result->response) {
                $response = $this->cookies->clearSession($result->response, $tenant);
                $cookie = $this->cookies->storePreSession($flow, $result->challenges);
                return $cookie->attach($response);
            }

            throw new UnauthorizedException();
        } catch (LoginException $ex) {
            return $this->renderStep($ex->getMessage(), $ex->auth, $input, $response, null, $ex->challenges ?? $state);
        } catch (UnauthorizedException $ex) {
            return $this->renderStep($ex->getMessage(), null, $input, $response, null, $state);
        }
    }

    private function requirePkce(OidcFlowContext $flow, ResponseInterface $response): ?ResponseInterface
    {
        if ($flow->codeChallenge === null) {
            return $this->redirectError($flow->tenant, $flow->redirect, 'invalid_request', $response);
        }
        try {
            PkceChallenge::fromRequest($flow->codeChallenge, $flow->codeChallengeMethod);
        } catch (\InvalidArgumentException) {
            return $this->redirectError($flow->tenant, $flow->redirect, 'invalid_request', $response);
        }
        return null;
    }

    private function buildContext(ServerRequestInterface $request, string $tenant): OidcFlowContext
    {
        return OidcFlowContext::fromRequest($request, $tenant, $this->context);
    }

    private function buildAuthRequest(OidcFlowContext $flow, ClientData $client): AuthenticationRequest
    {
        return new AuthenticationRequest(
            client: $client,
            scope: $flow->scope,
            redirect: $flow->redirect,
            responseType: $flow->responseType,
            audiences: array_values(array_unique([$flow->clientId, ...$flow->audiences]))
        );
    }

    private function verifyClient(string $clientId, string $tenant, string $redirect, string $scope): ClientData
    {
        $client = $this->clients->publicClientData($clientId, $tenant, $redirect, $scope);
        if (!$client) {
            throw new UnauthorizedException('Client not allowed');
        } else {
            return $client;
        }
    }

    private function redirectError(string $tenant, string $redirect, string $error, ResponseInterface $response): ResponseInterface
    {
        $response = $response->withStatus(302)->withHeader('Location', $redirect . '#error=' . urlencode($error));
        return $this->cookies->clearSession($response, $tenant);
    }

    private function renderStep(?string $message, ?AuthenticationResult $error, StepInput $input, ResponseInterface $response, ?string $stepOverride, ?ChallengesState $challengesOverride): ResponseInterface
    {
        $error = $error === null && $message !== null && $message !== ''
            ? new AuthenticationResult(valid: false, errorMessage: $message)
            : $error;
        $step = $error ? null : ($stepOverride ?? ($input->request->getQueryParams()['step'] ?? null));
        if ($challengesOverride !== null) {
            $input = new StepInput(
                context: $input->context,
                authRequest: $input->authRequest,
                challenges: $challengesOverride,
                body: $input->body,
                request: $input->request
            );
        }
        $result = $this->executeStep($input, $response, $error, $step, null);
        if ($result->type !== StepResult::TYPE_RENDER || !$result->response) {
            throw new UnauthorizedException();
        }
        $response = $this->cookies->clearSession($result->response, $input->context->tenant);
        $cookie = $this->cookies->storePreSession($input->context, $result->challenges);
        return $cookie->attach($response);
    }

    private function executeStep(
        StepInput $input,
        ResponseInterface $response,
        ?AuthenticationResult $error,
        ?string $step,
        ?string $csid
    ): StepResult {
        $result = $this->router->run($input, $response, $error, $step, $csid);
        if (!$result) {
            throw new UnauthorizedException();
        }
        return $result;
    }

    private function buildStepInput(
        OidcFlowContext $flow,
        ServerRequestInterface $request,
        AuthenticationRequest $authRequest,
        ChallengesState $state,
        ?array $body
    ): StepInput {
        return new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: $state,
            body: $body ?? [],
            request: $request
        );
    }

    private function redirectToLogin(
        ResponseInterface $response,
        OidcFlowContext $flow,
        AuthenticationRequest $authRequest
    ): ResponseInterface {
        if ($flow->prompt === 'none') {
            return $this->redirectError($flow->tenant, $flow->redirect, 'Only refresh from same device', $response);
        } else {
            $url = $this->urlBuilder->authorizeUrl(
                $authRequest,
                $flow->tenant,
                $flow->state,
                $flow->nonce,
                ['prompt' => $flow->prompt]
            );
            $response = $response->withStatus(302)->withHeader('Location', $url);
            return $this->cookies->clearSession($response, $flow->tenant);
        }
    }

    private function cisdPage(
        RequestInterface $request,
        ResponseInterface $response,
        OidcFlowContext $flow,
        AuthenticationRequest $authRequest
    ): ResponseInterface {
        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->autoSubmit("refresh")
        ]);
        $url = $this->urlBuilder->checkSessionUrl(
            $authRequest,
            $flow->tenant,
            $flow->state,
            $flow->nonce,
            ['prompt' => $flow->prompt]
        );
        $response->getBody()->write($this->decorator->getFullPage($request, 'Mfa', $js . "<h1>Verifiy login source...</h1>"
            . "<form id=\"refresh\" action=\"".$url."\" method=\"POST\">"
            . "<input type=\"hidden\" name=\"csid\" id=\"sign\" />"
            . "<input type=\"submit\" />"
            . "</form>", $flow->locale));
        return $response;
    }
}
